// lib/emit.mjs
// Renderers shared by more than one runtime emitter.

export const json = value => `${JSON.stringify(value, null, 2)}\n`

// A markdown slash command that hands the user's arguments to a skill.
export function markdownCommand(skill, { hint = true } = {}) {
  return [
    '---',
    `description: ${JSON.stringify(skill.description)}`,
    ...(hint ? [`argument-hint: ${JSON.stringify(skill.hint)}`] : []),
    '---',
    '',
    '<!-- Generated by no-vibe. Do not edit. -->',
    '',
    `Invoke the \`${skill.name}\` skill and follow it exactly.`,
    '',
    '**User intent:** $ARGUMENTS',
    '',
  ].join('\n')
}
